mapper.select:
SELECT T1.ENTRUST_ID entrustId, T1.ENTRUST_STATUS entrustStatus, T1.PORTFOLIO_ID portfolioId, T2.PORTFOLIO_NAME portfolioName, T3.EXC_DEAL_TYPE excDealType, T3.CUR_PAIR curPair, T1.PS ps, T1.VDATE vdate, T1.MDATE mdate, T3.SETTLE_SPREED settleSpreed, T1.PRICE price, T1.CCY ccy, T1.ENTRUST_AMT entrustAmt, T3.COR_CCY corCcy, T3.EXP_COR_AMT expCorAmt, IFNULL(T4.FINISH_AMT,0) finishAmt, round(IFNULL(T4.FINISH_AMT,0)/T1.ENTRUST_AMT,4)*100 tradeFinishAmt, T1.REMARK remark FROM ETR_ENTRUST T1 left join PTL_PORTFOLIO T2 on T2.PORTFOLIO_ID = T1.PORTFOLIO_ID inner join ETR_ENTRUST_ADD T3 on T3.ENTRUST_ID = T1.ENTRUST_ID left join (SELECT ENTRUST_ID ,SUM(FINISH_AMT) FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T4 on T4.ENTRUST_ID=T1.ENTRUST_ID inner join PTL_PORTFOLIO_AUTHORITY T5 on T2.PORTFOLIO_ID=T5.PORTFOLIO_ID and T5.USER_ID= #{loginUser}
AND (T2.PORTFOLIO_ID IN
#{prot}
or T2.PARENT_PORTFOLIO_ID IN
#{prot}
)
AND T3.EXC_DEAL_TYPE in
#{item}
AND T3.CUR_PAIR in
#{item}
AND T1.PS in
#{item}
AND T1.ENTRUST_STATUS in
#{item}
AND T1.VDATE >= STR_TO_DATE(#{startDate},'%Y-%m-%d')
AND T1.MDATE <=STR_TO_DATE(#{endDate},'%Y-%m-%d')
AND T1.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F11}
ORDER BY T1.ENTRUST_ID DESC
